import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64
.visible .entry sgemm_nn_f32(
    .param .u64 A_ptr,
    .param .u64 B_ptr,
    .param .u64 C_ptr,
    .param .u32 N_param
)
{
    .reg .pred %p<10>;
    .reg .b32 %r<64>;
    .reg .b64 %rd<64>;
    .reg .f32 %f<16>;
    // Named registers used below
    .reg .b64 %rdA, %rdB, %rdC, %rdSmemA, %rdSmemB;
    .reg .b32 %rN, %rTidX, %rTidY, %rBlkX, %rBlkY, %rBlkDimX, %rBlkDimY;
    .reg .b32 %rRow, %rCol, %rTile, %rK0, %rAcol, %rBrow, %rSmA_idx, %rSmB_idx, %rK;
    .reg .pred %pRowIn, %pAColIn, %pAin, %pBRowIn, %pColIn, %pBin, %pStoreRow, %pStoreCol, %pStore;
    .reg .f32 %fAcc, %fA, %fB, %fA2, %fB2;
    .shared .align 16 .b8 smemA[1024]; // 16*16*4
    .shared .align 16 .b8 smemB[1024]; // 16*16*4
    // Load params
    ld.param.u64 %rdA, [A_ptr];
    ld.param.u64 %rdB, [B_ptr];
    ld.param.u64 %rdC, [C_ptr];
    ld.param.u32 %rN, [N_param];
    // Convert param pointers from generic to global space
    cvta.to.global.u64 %rdA, %rdA;
    cvta.to.global.u64 %rdB, %rdB;
    cvta.to.global.u64 %rdC, %rdC;
    // Thread/block indices
    mov.u32 %rTidX, %tid.x;
    mov.u32 %rTidY, %tid.y;
    mov.u32 %rBlkX, %ctaid.x;
    mov.u32 %rBlkY, %ctaid.y;
    mov.u32 %rBlkDimX, %ntid.x;
    mov.u32 %rBlkDimY, %ntid.y;
    // Compute row and col
    mul.lo.u32 %r0, %rBlkY, %rBlkDimY;
    add.u32 %rRow, %r0, %rTidY;
    mul.lo.u32 %r1, %rBlkX, %rBlkDimX;
    add.u32 %rCol, %r1, %rTidX;
    // Tile size = 16
    mov.u32 %rTile, 16;
    // Accumulator = 0.0f
    mov.f32 %fAcc, 0f00000000;
    // Shared memory base addresses
    mov.u64 %rdSmemA, smemA;
    mov.u64 %rdSmemB, smemB;
    // k0 loop
    mov.u32 %rK0, 0;
BB_LOOP_K0:
    setp.ge.u32 %p0, %rK0, %rN;
    @%p0 bra BB_AFTER_LOOP;
    // a_col = k0 + tx
    add.u32 %rAcol, %rK0, %rTidX;
    // b_row = k0 + ty
    add.u32 %rBrow, %rK0, %rTidY;
    // In-bounds checks for A and B loads
    setp.lt.u32 %pRowIn, %rRow, %rN;
    setp.lt.u32 %pAColIn, %rAcol, %rN;
    and.pred %pAin, %pRowIn, %pAColIn;
    setp.lt.u32 %pBRowIn, %rBrow, %rN;
    setp.lt.u32 %pColIn, %rCol, %rN;
    and.pred %pBin, %pBRowIn, %pColIn;
    // Load A[row, a_col] or 0
    mov.f32 %fA, 0f00000000;
    @!%pAin bra SKIP_A_LOAD;
        mul.wide.u32 %rd2, %rRow, %rN;         // row * N
        cvt.u64.u32 %rd3, %rAcol;              // a_col
        add.u64 %rd4, %rd2, %rd3;              // row*N + a_col
        shl.b64 %rd5, %rd4, 2;                 // *4
        add.u64 %rd6, %rdA, %rd5;              // &A[row, a_col]
        ld.global.f32 %fA, [%rd6];
SKIP_A_LOAD:
    // Load B[b_row, col] or 0
    mov.f32 %fB, 0f00000000;
    @!%pBin bra SKIP_B_LOAD;
        mul.wide.u32 %rd7, %rBrow, %rN;        // b_row * N
        cvt.u64.u32 %rd8, %rCol;               // col
        add.u64 %rd9, %rd7, %rd8;              // b_row*N + col
        shl.b64 %rd10, %rd9, 2;                // *4
        add.u64 %rd11, %rdB, %rd10;            // &B[b_row, col]
        ld.global.f32 %fB, [%rd11];
SKIP_B_LOAD:
    // Store tiles to shared memory
    // A tile index: ty*tile + tx
    mul.lo.u32 %r2, %rTidY, %rTile;
    add.u32 %rSmA_idx, %r2, %rTidX;
    cvt.u64.u32 %rd12, %rSmA_idx;
    shl.b64 %rd13, %rd12, 2;
    add.u64 %rd14, %rdSmemA, %rd13;
    st.shared.f32 [%rd14], %fA;
    // B tile index: ty*tile + tx
    mul.lo.u32 %r3, %rTidY, %rTile;
    add.u32 %rSmB_idx, %r3, %rTidX;
    cvt.u64.u32 %rd15, %rSmB_idx;
    shl.b64 %rd16, %rd15, 2;
    add.u64 %rd17, %rdSmemB, %rd16;
    st.shared.f32 [%rd17], %fB;
    // Synchronize before compute
    bar.sync 0;
    // Inner accumulation over the tile dimension
    mov.u32 %rK, 0;
BB_INNER_K:
    setp.ge.u32 %p1, %rK, %rTile;
    @%p1 bra BB_END_INNER;
    // Load a = smemA[ty*tile + k]
    mul.lo.u32 %r4, %rTidY, %rTile;
    add.u32 %r5, %r4, %rK;
    cvt.u64.u32 %rd18, %r5;
    shl.b64 %rd19, %rd18, 2;
    add.u64 %rd20, %rdSmemA, %rd19;
    ld.shared.f32 %fA2, [%rd20];
    // Load b = smemB[k*tile + tx]
    mul.lo.u32 %r6, %rK, %rTile;
    add.u32 %r7, %r6, %rTidX;
    cvt.u64.u32 %rd21, %r7;
    shl.b64 %rd22, %rd21, 2;
    add.u64 %rd23, %rdSmemB, %rd22;
    ld.shared.f32 %fB2, [%rd23];
    // acc += a*b
    fma.rn.f32 %fAcc, %fA2, %fB2, %fAcc;
    add.u32 %rK, %rK, 1;
    bra BB_INNER_K;
BB_END_INNER:
    // Synchronize before loading next tiles
    bar.sync 0;
    // Next tile
    add.u32 %rK0, %rK0, %rTile;
    bra BB_LOOP_K0;
BB_AFTER_LOOP:
    // Store C[row, col] if within bounds
    setp.lt.u32 %pStoreRow, %rRow, %rN;
    setp.lt.u32 %pStoreCol, %rCol, %rN;
    and.pred %pStore, %pStoreRow, %pStoreCol;
    @!%pStore bra SKIP_STORE;
        mul.wide.u32 %rd24, %rRow, %rN;
        cvt.u64.u32 %rd25, %rCol;
        add.u64 %rd26, %rd24, %rd25;
        shl.b64 %rd27, %rd26, 2;
        add.u64 %rd28, %rdC, %rd27;
        st.global.f32 [%rd28], %fAcc;
SKIP_STORE:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("sgemm_nn_f32")

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        if not (A.is_cuda and B.is_cuda):
            raise RuntimeError("Inputs must be CUDA tensors.")
        if A.dtype != torch.float32 or B.dtype != torch.float32:
            raise RuntimeError("Inputs must be float32.")
        if A.dim() != 2 or B.dim() != 2 or A.shape[0] != A.shape[1] or B.shape[0] != B.shape[1] or A.shape != B.shape:
            raise RuntimeError("Inputs must be square matrices of the same shape.")
        if not (A.is_contiguous() and B.is_contiguous()):
            raise RuntimeError("Inputs must be contiguous.")
        if A.device != B.device:
            raise RuntimeError("Inputs must be on the same device.")

        N = A.shape[0]
        C = torch.empty((N, N), device=A.device, dtype=A.dtype)

        # Launch PTX kernel
        module = _get_ptx_module()
        TILE = 16
        grid_x = (N + TILE - 1) // TILE
        grid_y = (N + TILE - 1) // TILE
        block_x = TILE
        block_y = TILE

        module.launch(
            "sgemm_nn_f32",
            grid=(grid_x, grid_y, 1),
            block=(block_x, block_y, 1),
            arguments=[A, B, C, i32(N)],
            shared_memory=0,
            stream=torch.cuda.current_stream(A.device),
        )
        return C

